INSERT INTO `jobs` (`id`, `title`, `description1`, `description2`) VALUES
(1, 'UI/UX Designer (IT)', '<ul>\r\n<li>$42.50/hr - $96.15/hr</li>\r\n<li>Full-time</li>\r\n<li>Internship</li>\r\n</ul>\r\n<br>', '<br>\r\n\r\n<h2>About The Job</h2>\r\n\r\n<br>\r\n\r\n<h3>Descreption</h3>\r\n\r\n<p>At Amazon, we hire the best minds in technology to innovate and build on behalf of our customers. The intense focus we have on our customers is why we are one of the world’s most beloved brands – customer obsession is part of our company DNA. Our interns write real software and collaborate with a select group of experienced software development engineers (SDEs) who guide interns on projects that matter to our customers.\r\n</p>\r\n<br>\r\n\r\n<h3>Basic Qualifications</h3>\r\n\r\n<ul>\r\n<li> Currently enrolled in an Associates, Bachelors, Masters, or PhD in Computer Science, Computer Engineering, Data Science, Electrical Engineering, or majors relating to these fields are considered with an expected graduation date between December 1, 2024 and September 30, 2025.</li> \r\n\r\n<li>Programming experience with at least one modern language such as Java, C++, or C# including object-oriented design.</li>\r\n\r\n<li>Knowledge of Computer Science fundamentals such as object-oriented design, algorithm design, data structures, problem solving, and complexity analysis.</li>\r\n</ul>\r\n\r\n<br>\r\n\r\n<h3>Preferred Qualifications</h3>\r\n\r\n<ul>\r\n<li>Currently enrolled in an Associates, Bachelors, Masters, or PhD in Computer Science, Computer Engineering, Data Science, Electrical Engineering, or majors relating to these fields are considered with an expected graduation date between December 1, 2024 and September 30, 2025.</li>\r\n\r\n<li>Programming experience with at least one modern language such as Java, C++, or C# including object-oriented design.</li> <li>Knowledge of Computer Science fundamentals such as object-oriented design, algorithm design, data structures, problem solving, and complexity analysis.</li>\r\n</ul>'),
(4, 'Markting', '<ul>\r\n<li>$42.50/hr - $96.15/hr</li>\r\n<li>Full-time</li>\r\n<li>Internship</li>\r\n</ul>\r\n<br>', '<br>\r\n\r\n<h2>About The Job</h2>\r\n\r\n<br>\r\n\r\n<h3>Descreption</h3>\r\n\r\n<p>At Amazon, we hire the best minds in technology to innovate and build on behalf of our customers. The intense focus we have on our customers is why we are one of the world’s most beloved brands – customer obsession is part of our company DNA. Our interns write real software and collaborate with a select group of experienced software development engineers (SDEs) who guide interns on projects that matter to our customers.\r\n</p>\r\n<br>\r\n\r\n<h3>Basic Qualifications</h3>\r\n\r\n<ul>\r\n<li> Currently enrolled in an Associates, Bachelors, Masters, or PhD in Computer Science, Computer Engineering, Data Science, Electrical Engineering, or majors relating to these fields are considered with an expected graduation date between December 1, 2024 and September 30, 2025.</li> \r\n\r\n<li>Programming experience with at least one modern language such as Java, C++, or C# including object-oriented design.</li>\r\n\r\n<li>Knowledge of Computer Science fundamentals such as object-oriented design, algorithm design, data structures, problem solving, and complexity analysis.</li>\r\n</ul>\r\n\r\n<br>\r\n\r\n<h3>Preferred Qualifications</h3>\r\n\r\n<ul>\r\n<li>Currently enrolled in an Associates, Bachelors, Masters, or PhD in Computer Science, Computer Engineering, Data Science, Electrical Engineering, or majors relating to these fields are considered with an expected graduation date between December 1, 2024 and September 30, 2025.</li>\r\n\r\n<li>Programming experience with at least one modern language such as Java, C++, or C# including object-oriented design.</li> <li>Knowledge of Computer Science fundamentals such as object-oriented design, algorithm design, data structures, problem solving, and complexity analysis.</li>\r\n</ul>');
